{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C25"],
      "claim": "Ampicillin, a small polar oral drug with an amino group, showed 62 ± 17% oral bioavailability in healthy fasting subjects, well above the 20% threshold and supporting high bioavailability for the small primary-amine adamantane query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C45"],
      "claim": "Amoxicillin, a close structural analogue of ampicillin, has human oral bioavailability of 75–93%, providing strong direct evidence that small amino-containing drugs can be highly orally bioavailable.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Maraviroc, a larger lipophilic basic drug with CYP3A4 and P-gp liabilities, still achieves 33% absolute oral bioavailability in humans; the query lacks such extensive first-pass/efflux liabilities, so high bioavailability is well supported.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C28"],
      "claim": "Perindopril, a small orally absorbed drug, has an absolute oral bioavailability of about 75%, supporting the pattern that small lipophilic oral molecules with basic/amine features reach F well above 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Gabapentin enacarbil, an orally absorbed small-molecule drug, shows bioavailability of at least 68% in healthy adults, further supporting high oral bioavailability for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Bicifadine, a small lipophilic amine, has an absolute oral bioavailability of approximately 67% in humans, directly supporting high F for a structurally similar small amine.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All retrieved experimental analogues have oral bioavailability values well above the 20% threshold, with very high assay-transfer scores (≈0.987–0.990). The query, rimantadine, is a small lipophilic primary-amine adamantane expected to be well absorbed, and no affirmative evidence supports low bioavailability.",
  "evidence_gaps": [
    "No direct rimantadine bioavailability record is present in the supplied evidence.",
    "All analogues are structurally distinct from the adamantane cage, although transfer scores are very high.",
    "No low-bioavailability analogue with F < 20% was provided to challenge the threshold decision."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

